import{_ as n,a0 as p,w as a,s as i,I as e,x as t,a1 as l,A as r,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"计算机实验室之树莓派：课程 2 OK02 | LCTT x X-CMD","titleTemplate":false,"description":"计算机实验室之树莓派：课程 2 OK02 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"计算机实验室之树莓派：课程 2 OK02 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"计算机实验室之树莓派：课程 2 OK02 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20120202 Computer Laboratory - Raspberry Pi- Lesson 2 OK02","title":"计算机实验室之树莓派：课程 2 OK02","tag":"201901","desc":""},"relativePath":"201901/20120202 Computer Laboratory - Raspberry Pi- Lesson 2 OK02.md","filePath":"[post].md"}'),u={name:"201901/20120202 Computer Laboratory - Raspberry Pi- Lesson 2 OK02.md"};function m(b,o,f,T,C,k){const s=p("Link");return a(),i("div",null,[o[32]||(o[32]=e("h1",{id:"计算机实验室之树莓派-课程-2-ok02",tabindex:"-1"},[t("计算机实验室之树莓派：课程 2 OK02 "),e("a",{class:"header-anchor",href:"#计算机实验室之树莓派-课程-2-ok02","aria-label":"Permalink to “计算机实验室之树莓派：课程 2 OK02”"},"​")],-1)),e("p",null,[o[1]||(o[1]=t("OK02 课程构建于 OK01 课程的基础上，通过不停地打开和关闭 OK 或 ACT LED 指示灯来实现闪烁。假设你已经有了 ",-1)),l(s,{href:"https://linux.cn/article-10458-1.html"},{default:r(()=>[...o[0]||(o[0]=[t("课程 1：OK01",-1)])]),_:1}),o[2]||(o[2]=t(" 操作系统的代码，它将是这一节课的基础。",-1))]),o[33]||(o[33]=d(`<h3 id="_1、等待" tabindex="-1">1、等待 <a class="header-anchor" href="#_1、等待" aria-label="Permalink to “1、等待”">​</a></h3><p>等待是操作系统开发中非常有用的部分。操作系统经常发现自己无事可做，以及必须要延迟。在这个例子中，我们希望通过等待，让 LED 灯打开、关闭的闪烁可以看到。如果你只是打开和关闭它，你将看到这个视觉效果，因为计算机每秒种可以打开和关闭它好几千次（LCTT 译注：视觉暂留效应会使你难以发觉它的闪烁）。在后面的课程中，我们将看到精确的等待，但是现在，我们只要简单地去消耗时间就足够了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mov r2,#0x3F0000</span></span>
<span class="line"><span>wait1$:</span></span>
<span class="line"><span>sub r2,#1</span></span>
<span class="line"><span>cmp r2,#0</span></span>
<span class="line"><span>bne wait1$</span></span></code></pre></div><blockquote><p><code>sub reg,#val</code> 从寄存器 <code>reg</code> 中的值上减去数字 <code>val</code></p><p><code>cmp reg,#val</code> 将寄存器中的值与数字 <code>val</code> 进行比较。</p><p>如果最后的比较结果是不相等，那么执行后缀了 <code>ne</code> 的 <code>b</code> 命令。</p></blockquote><p>上面是一个很常见的产生延迟的代码片段，由于每个树莓派基本上是相同的，所以产生的延迟大致也是相同的。它的工作原理是，使用一个 <code>mov</code> 命令将值 3F0000<sub>16</sub> 推入到寄存器 <code>r2</code> 中，然后将这个值减 1，直到这个值减到 0 为止。在这里使用了三个新命令 <code>sub</code>、 <code>cmp</code> 和 <code>bne</code>。</p><p><code>sub</code> 是减法命令，它只是简单地从第一个参数中的值减去第二个参数中的值。</p><p><code>cmp</code> 是个很有趣的命令。它将第一个参数与第二个参数进行比较，然后将比较结果记录到一个称为当前处理器状态寄存器的专用寄存器中。你其实不用担心它，它记住的只是两个数谁大或谁小，或是相等而已。[^1]</p><p><code>bne</code> 其实是一个伪装的分支命令。在 ARM 汇编语言家族中，任何指令都可以有条件地运行。这意味着如果上一个比较结果是某个确定的结果，那个指令才会运行。这是个非常有意思的技巧，我们在后面将大量使用到它，但在本案例中，我们在 <code>b</code> 命令后面的 <code>ne</code> 后缀意思是 “只有在上一个比较的结果是值不相等，才去运行该分支”。<code>ne</code> 后缀可以使用在任何命令上，其它几个（总共 16 个）条件也是如此，比如 <code>eq</code> 表示等于，而 <code>lt</code> 表示小于。</p><h3 id="_2、组合到一起" tabindex="-1">2、组合到一起 <a class="header-anchor" href="#_2、组合到一起" aria-label="Permalink to “2、组合到一起”">​</a></h3>`,9)),e("p",null,[o[4]||(o[4]=t("上一节讲我提到过，通过将 GPIO 地址偏移量设置为 28（即：",-1)),o[5]||(o[5]=e("code",null,"str r1,[r0,#28]",-1)),o[6]||(o[6]=t("）而不是 40 即可实现 LED 的关闭。因此，你需要去修改课程 OK01 的代码，在打开 LED 后，运行等待代码，然后再关闭 LED，再次运行等待代码，并包含一个回到开始位置的分支。注意，不需要重新启用 GPIO 的 16 号针脚的输出功能，这个操作只需要做一次就可以了。如果你想更高效，我建议你复用 ",-1)),o[7]||(o[7]=e("code",null,"r1",-1)),o[8]||(o[8]=t(" 寄存器的值。所有课程都一样，你可以在 ",-1)),l(s,{href:"https://www.cl.cam.ac.uk/projects/raspberrypi/tutorials/os/downloads.html"},{default:r(()=>[...o[3]||(o[3]=[t("下载页面",-1)])]),_:1}),o[9]||(o[9]=t(" 找到所有的解决方案。需要注意的是，必须保证你的所有标签都是唯一的。当你写了 ",-1)),o[10]||(o[10]=e("code",null,"wait1$:",-1)),o[11]||(o[11]=t(" 你其它行上的标签就不能再使用 ",-1)),o[12]||(o[12]=e("code",null,"wait1$",-1)),o[13]||(o[13]=t(" 了。",-1))]),o[34]||(o[34]=e("p",null,[t("在我的树莓派上，它大约是每秒闪两次。通过改变我们所设置的 "),e("code",null,"r2"),t(" 寄存器中的值，可以很轻松地修改它。但是，不幸的是，我不能够精确地预测它的运行速度。如果你的树莓派未按预期正常工作，请查看我们的故障排除页面，如果它正常工作，恭喜你。")],-1)),o[35]||(o[35]=e("p",null,[t("在这个课程中，我们学习了另外两个汇编命令："),e("code",null,"sub"),t(" 和 "),e("code",null,"cmp"),t("，同时学习了 ARM 中如何实现有条件运行。")],-1)),e("p",null,[o[15]||(o[15]=t("在下一个课程，",-1)),l(s,{href:"https://www.cl.cam.ac.uk/projects/raspberrypi/tutorials/os/ok03.html"},{default:r(()=>[...o[14]||(o[14]=[t("课程 3：OK03",-1)])]),_:1}),o[16]||(o[16]=t(" 中我们将学习如何编写代码，以及建立一些代码复用的标准，并且如果需要的话，可能会使用 C 或 C++ 来写代码。",-1))]),o[36]||(o[36]=d("<p>[^1]: 如果你点了这个链接，说明你一定想知道它的具体内容。CPSR 是一个由许多独立的比特位组成的 32 比特寄存器。它有一个位用于表示正数、零和负数。当一个 <code>cmp</code> 指令运行后，它从第一个参数上减去第二个参数，然后用这个位记下它的结果是正数、零还是负数。如果是零意味着它们相等（<code>a-b=0</code> 暗示着 <code>a=b</code>）如果为正数意味着 a 大于 b（<code>a-b&gt;0</code> 暗示着 <code>a&gt;b</code>），如果为负数意味着小于。还有其它比较指令，但 <code>cmp</code> 指令最直观。</p><hr>",2)),e("p",null,[o[18]||(o[18]=t("via: ",-1)),l(s,{href:"https://www.cl.cam.ac.uk/projects/raspberrypi/tutorials/os/ok02.html"},{default:r(()=>[...o[17]||(o[17]=[t("https://www.cl.cam.ac.uk/projects/raspberrypi/tutorials/os/ok02.html",-1)])]),_:1})]),e("p",null,[o[23]||(o[23]=t("作者：",-1)),l(s,{href:"http://www.cl.cam.ac.uk/~rdm34"},{default:r(()=>[...o[19]||(o[19]=[t("Robert Mullins",-1)])]),_:1}),o[24]||(o[24]=t(" 选题：",-1)),l(s,{href:"https://github.com/lujun9972"},{default:r(()=>[...o[20]||(o[20]=[t("lujun9972",-1)])]),_:1}),o[25]||(o[25]=t(" 译者：",-1)),l(s,{href:"https://github.com/qhwdw"},{default:r(()=>[...o[21]||(o[21]=[t("qhwdw",-1)])]),_:1}),o[26]||(o[26]=t(" 校对：",-1)),l(s,{href:"https://github.com/wxy"},{default:r(()=>[...o[22]||(o[22]=[t("wxy",-1)])]),_:1})]),e("p",null,[o[29]||(o[29]=t("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[27]||(o[27]=[t("LCTT",-1)])]),_:1}),o[30]||(o[30]=t(" 原创编译，",-1)),l(s,{href:"https://linux.cn/"},{default:r(()=>[...o[28]||(o[28]=[t("Linux中国",-1)])]),_:1}),o[31]||(o[31]=t(" 荣誉推出",-1))])])}const O=n(u,[["render",m]]);export{L as __pageData,O as default};
